  setConfig(config) {
    if (!config || !(config.entity || config.mower_entity || config.status_entity || config.map_entity)) {
      throw new Error("Navimower Map Card: select a mower entity");
    }
    const previousEntity = this._config?.entity || this._config?.mower_entity || this._config?.status_entity;
    const previousScheduleEntity = this._config?.schedule_entity || null;
    const previousScheduleSwitchEntity = this._config?.schedule_switch_entity || null;
    const incoming = { ...config };
    if (!incoming.entity && incoming.mower_entity) incoming.entity = incoming.mower_entity;
    this._config = { ...DEFAULTS, ...incoming };
    this._config.auto_entities = normalizeBoolean(incoming.auto_entities, DEFAULTS.auto_entities);
    this._resolutionKey = null;
    this._resolved = {};
    this._deviceId = null;
    this._mapKey = null;
    this._layout = null;
    this._initialViewApplied = false;
    this._lastLiveSnapshot = null;
    this._resetRenderKeys();
    if (previousEntity !== this._config.entity) {
      this._mapPayload = null;
      this._mapStaticSignature = null;
      this._activeSessionDrawable = false;
      this._trail = [];
      this._trailSession = null;
      this._lastPointKey = null;
      this._scheduleDialogOpen = false;
      this._scheduleDraft = null;
      this._scheduleServerDays = [];
      this._scheduleZones = [];
      this._scheduleSignature = null;
      this._scheduleStatus = {};
    }
    if (previousScheduleEntity !== this._config.schedule_entity
      || previousScheduleSwitchEntity !== this._config.schedule_switch_entity) {
      this._scheduleDraft = null;
      this._scheduleServerDays = [];
      this._scheduleZones = [];
      this._scheduleSignature = null;
      this._scheduleStatus = {};
    }
    this._ensureDom();
    this._renderShell();
    if (this._hass) {
      this._resolveEntities();
      this._maybeLoadMap();
      this._updateLive(true);
    }
  }

  set hass(hass) {
    this._hass = hass;
    if (!this._config) return;
    this._ensureDom();
    this._resolveEntities();
    this._maybeLoadMap();
    this._updateLive(false);
  }

  getCardSize() {
    return this._config?.show_session_legend === false ? 7 : 8;
  }

  getGridOptions() {
    return {
      rows: 8,
      columns: 6,
      min_rows: 5,
      min_columns: 3,
    };
  }

  connectedCallback() {
    this._connected = true;
    if (this._refreshAfterReconnect && this._config && this._hass) {
      this._refreshAfterReconnect = false;
      this._mapKey = null;
      this._maybeLoadMap();
      this._updateLive(true);
    }
  }

  disconnectedCallback() {
    this._connected = false;
    this._refreshAfterReconnect = true;
    this._pointers.clear();
    this._panStart = null;
    this._pinchStart = null;
    this._interactivePointer = null;
    if (this._pulseTimer) clearTimeout(this._pulseTimer);
    this._pulseTimer = null;
    for (const timer of Object.values(this._scheduleStatusTimers || {})) clearTimeout(timer);
    this._scheduleStatusTimers = {};
    if (this._renderHandle !== null) {
      const cancel = globalThis.cancelAnimationFrame || globalThis.clearTimeout;
      cancel?.(this._renderHandle);
      this._renderHandle = null;
    }
    this._pendingRender = {};
  }

  _resetRenderKeys() {
    this._shellRenderKey = null;
    this._historyBarRenderKey = null;
    this._historyRenderKey = null;
    this._trailRenderKey = null;
    this._mowerRenderKey = null;
    this._footerRenderKey = null;
    this._controlsRenderKey = null;
    this._sessionsRenderKey = null;
    this._messageRenderKey = null;
    this._staticRenderKey = null;
  }

  _queueRender(flags = {}) {
    for (const [key, value] of Object.entries(flags)) {
      if (value) this._pendingRender[key] = true;
    }
    if (this._renderHandle !== null) return;
    const schedule = globalThis.requestAnimationFrame || ((callback) => globalThis.setTimeout(callback, 0));
    this._renderHandle = schedule(() => {
      this._renderHandle = null;
      const pending = this._pendingRender;
      this._pendingRender = {};
      if (pending.shell) this._renderShell();
      if (pending.history) this._renderHistory();
      if (pending.trail) this._renderTrail();
      if (pending.mower) this._renderMower();
      if (pending.footer) this._renderFooter();
      if (pending.controls) this._renderControls();
      if (pending.dialog) {
        if (this._scheduleDialogOpen) this._syncScheduleDraft();
        this._renderDialog();
      }
      if (pending.sessions) this._renderSessions();
      if (pending.message) this._renderMessage();
    });
  }

